Contents of file backend/src/billing.ts:

1 | import { PLAN_PRICE, TAX_RATE, TODAY, customers, invoices } from './data.js'
2 | import type { Invoice } from './data.js'
3 | 
4 | const round = (n: number) => Math.round(n * 100) / 100
5 | 
6 | /** Subtotal, tax and total are always derived from the line items, never stored. */
7 | export function totals(invoice: Invoice) {
8 |   const subtotal = round(invoice.lines.reduce((sum, l) => sum + l.quantity * l.unitPrice, 0))
9 |   const tax = round(subtotal * TAX_RATE)
10 |   return { subtotal, tax, total: round(subtotal + tax) }
11 | }
12 | 
13 | /** An open invoice past its due date. Drafts and paid invoices are never overdue. */
14 | export function isOverdue(invoice: Invoice) {
15 |   return invoice.status === 'open' && invoice.dueAt < TODAY
16 | }
17 | 
18 | /** Money still owed by a customer: the total of their open invoices. */
19 | export function balance(customerId: string) {
20 |   return round(
21 |     invoices
22 |       .filter((i) => i.customerId === customerId && i.status === 'open')
23 |       .reduce((sum, i) => sum + totals(i).total, 0),
24 |   )
25 | }
26 | 
27 | /** Monthly recurring revenue: the list price of every customer's plan, before tax. */
28 | export function mrr() {
29 |   return customers.reduce((sum, c) => sum + PLAN_PRICE[c.plan], 0)
30 | }
31 | 
32 | export function customerName(customerId: string) {
33 |   return customers.find((c) => c.id === customerId)?.name ?? 'Unknown customer'
34 | }
